"use strict";

// Renders hub.json (generated by scripts/build_catalog.py). Plain browser JavaScript, no build step.
// Asset and data paths are root-absolute so path-based routes served through the
// navigationFallback in staticwebapp.config.json still load them.

const HUB_DATA_URL = "/hub.json";

const state = {
  config: null,
  build: null,
  skills: [],
  activeKind: "all",
  activeTag: "",
  query: "",
};

async function bootstrap() {
  try {
    const res = await fetch(HUB_DATA_URL, { cache: "no-store" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    state.config = data.config;
    state.build = data.build || null;
    state.skills = data.skills;
    renderAll();
    wireStaticEvents();
  } catch (err) {
    renderError(err);
  }
}

function renderError(err) {
  const detail = document.querySelector("#skill-detail");
  if (detail && !detail.hidden) {
    detail.replaceChildren(
      el("a", { href: "/" }, "Back to catalog"),
      el("h2", {}, "Couldn't load skill details"),
      el("p", {}, `Couldn't load catalog data (${err.message}). Try reloading this page.`),
    );
    return;
  }
  const grid = document.querySelector("#skills-grid");
  if (grid) grid.replaceChildren();
  const empty = document.querySelector("#empty-state");
  if (empty) {
    empty.hidden = false;
    empty.textContent = `Couldn't load catalog data (${err.message}). Run \`npm run build\`.`;
  }
  setText("#result-count", "0 skills");
}

function renderAll() {
  applyTheme(state.config.theme);
  renderHero();
  renderBuildBadge();
  renderFooter();
  if (showRoute()) return;
  restoreFilters();
  renderSignal();
  renderTagCloud();
  renderCards();
  applyFilters();
}

function skillRoute(pathname) {
  if (pathname === "/" || pathname === "/index.html") return { catalog: true };
  const match = /^\/skills\/([a-z0-9]+(?:-[a-z0-9]+)*)\/?$/.exec(pathname);
  return { catalog: false, name: match ? match[1] : null };
}

function showRoute() {
  const route = skillRoute(window.location.pathname);
  const catalog = document.querySelector("#catalog");
  const detail = document.querySelector("#skill-detail");
  catalog.hidden = !route.catalog;
  detail.hidden = route.catalog;
  document.querySelector(".hero-actions").hidden = !route.catalog;
  document.querySelector(".signal-panel").hidden = !route.catalog;
  document.querySelector(".hero").classList.toggle("detail-header", !route.catalog);
  setAttr(".skip-link", "href", route.catalog ? "#catalog" : "#skill-detail");
  setText(".skip-link", route.catalog ? "Skip to the catalog" : "Skip to skill details");
  if (route.catalog) return false;
  const skill = state.skills.find((item) => item.name === route.name);
  if (skill) {
    document.title = `${skill.title} | ${state.config.title}`;
    setText("#hub-title", skill.title);
    setText("#hub-tagline", state.config.title);
    setAttr("meta[name=description]", "content", skill.description);
    renderSkillDetail(skill);
  } else {
    document.title = `Skill not found | ${state.config.title}`;
    setText("#hub-title", "Skill not found");
    setText("#hub-tagline", "This address does not match a skill in the catalog.");
    detail.replaceChildren(el("a", { href: "/" }, "Back to catalog"));
  }
  return true;
}

function detailSection(title, text) {
  const section = el("section", { class: "detail-section" });
  section.append(el("h2", {}, title), el("p", {}, text));
  return section;
}

function renderSkillDetail(skill) {
  const detail = document.querySelector("#skill-detail");
  detail.replaceChildren(el("a", { href: "/" }, "Back to catalog"));
  detail.append(
    detailSection("What it does", skill.description),
    detailSection("When to use", skill.whenToUse),
  );
  const provenance = el("section", { class: "detail-section" });
  provenance.append(el("h2", {}, "Where it comes from"));
  const facts = el("dl", { class: "provenance" });
  for (const [label, value] of [
    ["Status", skill.agentSkill ? `${skill.kind} / project skill` : skill.kind],
    ["Credited source", skill.source],
    ["License", skill.license],
    ...(skill.kind === "local" ? [["Hub repository", state.config.repo]] : []),
  ]) {
    const row = el("div", {});
    row.append(el("dt", {}, label), el("dd", {}, value));
    facts.append(row);
  }
  provenance.append(facts);
  provenance.append(el("a", { href: skill.url, rel: "noreferrer" },
    skill.kind === "local" ? "View hub source and supporting files" : "View upstream source"));
  detail.append(provenance);
  const install = el("section", { class: "detail-section" });
  install.append(el("h2", {}, "Install"), createInstallRow(skill));
  if (skill.footprint) install.append(createFootprint(skill.footprint));
  detail.append(install);
  const file = detailSection("Full skill file", skill.kind === "local"
    ? "Complete SKILL.md, including frontmatter. This is the hub's build-time copy, not a live upstream version. Supporting files are available through the hub source link above."
    : "The full skill file is not hosted in this hub. Read it at the upstream source.");
  if (skill.kind === "local") {
    const pre = el("pre", { class: "skill-file" });
    pre.append(el("code", {}, skill.skillFile));
    file.append(pre);
  } else {
    file.append(el("a", { href: skill.url, rel: "noreferrer" }, "Read skill upstream"));
  }
  detail.append(file);
}

function restoreFilters() {
  const params = new URLSearchParams(window.location.search);
  state.query = params.get("q") || "";
  const kind = params.get("kind");
  state.activeKind = ["local", "external"].includes(kind) ? kind : "all";
  state.activeTag = params.get("tag") || "";
  document.querySelector("#search").value = state.query;
  updateFilterButtons();
}

function saveFilters() {
  const url = new URL(window.location.href);
  for (const [key, value] of [
    ["q", state.query],
    ["kind", state.activeKind === "all" ? "" : state.activeKind],
    ["tag", state.activeTag],
  ]) {
    if (value) url.searchParams.set(key, value);
    else url.searchParams.delete(key);
  }
  window.history.replaceState(null, "", url.pathname + url.search + url.hash);
}

function updateFilterButtons() {
  for (const [selector, key, activeValue] of [
    [".filter", "kind", state.activeKind],
    [".tag-filter", "tag", state.activeTag],
  ]) {
    document.querySelectorAll(selector).forEach((button) => {
      const active = button.dataset[key] === activeValue;
      button.classList.toggle("active", active);
      button.setAttribute("aria-pressed", String(active));
    });
  }
}

function applyTheme(theme) {
  if (!theme) return;
  const properties = { "--accent": theme.accent, "--accent-ink": theme.ink, "--link": theme.link };
  for (const [name, value] of Object.entries(properties)) {
    if (value) document.documentElement.style.setProperty(name, value);
  }
}

function renderHero() {
  const cfg = state.config;
  document.title = cfg.title;
  const desc = document.querySelector("meta[name=description]");
  if (desc) desc.setAttribute("content", cfg.tagline);
  setText("#hub-eyebrow", cfg.eyebrow);
  setText("#hub-title", cfg.title);
  setText("#hub-tagline", cfg.tagline);
  setText("#hub-cta", cfg.primaryCta || "");
  setText("#hub-install-cmd", featuredInstallCommand(cfg, state.skills));
  setAttr("#repo-link", "href", `https://github.com/${cfg.repo}`);
}

function featuredInstallCommand(cfg, skills) {
  const name = cfg.featuredSkill || "grilling";
  const featured = skills.find((skill) => skill.kind === "local" && skill.name === name);
  return featured ? featured.installCommand : `gh skill install ${cfg.repo} ${name}`;
}

function buildLink(build, repo) {
  if (!build || !repo) return "";
  if (build.env === "preview" && build.pr) return `https://github.com/${repo}/pull/${build.pr}`;
  if (build.sha) return `https://github.com/${repo}/commit/${build.sha}`;
  return "";
}

function renderBuildBadge() {
  const badge = document.querySelector("#build-badge");
  if (!badge) return;
  const build = state.build || { env: "local", label: "Local build" };
  badge.textContent = build.label || "Local build";
  badge.dataset.env = build.env || "local";
  const href = buildLink(build, state.config.repo);
  if (href) {
    badge.setAttribute("href", href);
    badge.setAttribute("title", `Built from commit ${build.sha}`);
  } else {
    badge.removeAttribute("href");
    badge.setAttribute("title", "Built on this machine");
  }
}

function renderSignal() {
  const local = state.skills.filter((s) => s.kind === "local").length;
  const external = state.skills.length - local;
  setText("#signal-total", String(state.skills.length));
  setText("#signal-local", String(local));
  setText("#signal-external", String(external));
  setText("#signal-owner", state.config.owner);
}

function renderTagCloud() {
  const allTags = [...new Set(state.skills.flatMap((s) => s.tags))].sort();
  const cloud = document.querySelector("#tag-cloud");
  cloud.replaceChildren();
  for (const tag of allTags) {
    const btn = el("button", { class: "tag-filter", type: "button", "aria-pressed": "false" }, tag);
    btn.dataset.tag = tag;
    btn.addEventListener("click", () => toggleTag(tag));
    cloud.append(btn);
  }
  updateFilterButtons();
}

function renderCards() {
  const grid = document.querySelector("#skills-grid");
  grid.replaceChildren();
  state.skills.forEach((skill, idx) => {
    grid.append(createCard(skill, idx));
  });
}

function renderFooter() {
  setText("#hub-notice", state.config.notice);
}

function searchText(skill) {
  return [skill.name, skill.title, skill.description, skill.kind, ...skill.tags].join(" ").toLowerCase();
}

function createCard(skill, idx) {
  const card = el("article", { class: "skill-card", style: `--delay: ${idx * 45}ms` });
  card.dataset.kind = skill.kind;
  card.dataset.name = skill.name;
  card.dataset.tags = JSON.stringify(skill.tags);
  card.dataset.search = searchText(skill);

  const topline = el("div", { class: "card-topline" });
  topline.append(
    el("span", { class: "kind" }, skill.agentSkill ? `${skill.kind} · project skill` : skill.kind),
    el("span", { class: "license" }, skill.license),
  );
  card.append(topline);

  const title = el("h3", {});
  title.append(el("a", { href: `/skills/${skill.name}` }, skill.title));
  card.append(title);
  card.append(el("p", { class: "description" }, skill.description));

  const tags = el("div", { class: "tags" });
  skill.tags.forEach((t) => tags.append(el("span", { class: "tag" }, t)));
  card.append(tags);

  if (skill.footprint) card.append(createFootprint(skill.footprint));

  card.append(createInstallRow(skill));

  const footer = el("div", { class: "card-footer" });
  footer.append(el("a", { href: skill.url, rel: "noreferrer" }, "Source"));
  if (skill.source) footer.append(el("span", { class: "source-name" }, skill.source));
  card.append(footer);

  return card;
}

function createInstallRow(skill) {
  const installRow = el("div", { class: "install-row" });
  installRow.append(el("code", {}, skill.installCommand));
  const copyBtn = el(
    "button",
    { class: "copy-button", type: "button", "aria-label": `Copy install command for ${skill.title}`, "aria-live": "polite" },
    "Copy",
  );
  copyBtn.dataset.command = skill.installCommand;
  copyBtn.addEventListener("click", () => copyInstall(copyBtn));
  installRow.append(copyBtn);
  return installRow;
}

// Context footprint: what a skill costs the agent, by when it is loaded (estimated tokens).
function createFootprint(footprint) {
  const box = el("div", { class: "footprint" });
  box.append(el("span", { class: "footprint-title" }, "Context footprint · est. tokens"));
  const list = el("dl", {});
  const files = footprint.files
    ? `${footprint.files} · ~${formatTokens(footprint.fileTokens)}`
    : "none";
  list.append(
    footprintItem("Always", `~${formatTokens(footprint.indexTokens)}`, "Name and description: in context in every session"),
    footprintItem("On use", `~${formatTokens(footprint.bodyTokens)}`, "SKILL.md instructions: loaded when the skill is used"),
    footprintItem("Files", files, "Supporting files: read only when the instructions need them"),
  );
  box.append(list);
  return box;
}

function footprintItem(label, value, hint) {
  const item = el("div", { title: hint });
  item.append(el("dt", {}, label), el("dd", {}, value));
  return item;
}

function formatTokens(count) {
  const n = Number(count);
  if (!Number.isFinite(n) || n <= 0) return "0";
  if (n < 1000) return String(Math.round(n));
  const thousands = n / 1000;
  return `${thousands < 9.95 ? thousands.toFixed(1).replace(/\.0$/, "") : Math.round(thousands)}k`;
}

function el(tag, attrs = {}, text) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "class") node.className = v;
    else node.setAttribute(k, v);
  }
  if (text !== undefined) node.textContent = text;
  return node;
}

function setText(sel, text) {
  const n = document.querySelector(sel);
  if (n) n.textContent = text;
}

function setAttr(sel, attr, value) {
  const n = document.querySelector(sel);
  if (n) n.setAttribute(attr, value);
}

async function copyInstall(btn) {
  const original = btn.textContent;
  try {
    await navigator.clipboard.writeText(btn.dataset.command);
    btn.textContent = "Copied";
    btn.classList.add("copied");
  } catch {
    btn.textContent = "Copy failed";
  }
  setTimeout(() => {
    btn.textContent = original;
    btn.classList.remove("copied");
  }, 1300);
}

function toggleTag(tag) {
  state.activeTag = state.activeTag === tag ? "" : tag;
  updateFilterButtons();
  saveFilters();
  applyFilters();
}

function setKind(kind) {
  state.activeKind = kind;
  updateFilterButtons();
  saveFilters();
  applyFilters();
}

// Tags match exactly: "demo" does not match "demo-tools" or a description that mentions demos.
function matchesFilters(card, filters) {
  const query = (filters.query || "").trim().toLowerCase();
  const kind = filters.activeKind || "all";
  const matchesQuery = !query || card.dataset.search.includes(query);
  const matchesKind = kind === "all" || card.dataset.kind === kind;
  const matchesTag = !filters.activeTag || JSON.parse(card.dataset.tags || "[]").includes(filters.activeTag);
  return matchesQuery && matchesKind && matchesTag;
}

function applyFilters() {
  let visible = 0;
  document.querySelectorAll(".skill-card").forEach((card) => {
    const show = matchesFilters(card, state);
    card.hidden = !show;
    if (show) visible += 1;
  });
  setText("#result-count", `${visible} ${visible === 1 ? "skill" : "skills"}`);
  const empty = document.querySelector("#empty-state");
  if (empty) empty.hidden = visible !== 0;
}

function wireStaticEvents() {
  const search = document.querySelector("#search");
  search.addEventListener("input", (e) => {
    state.query = e.target.value;
    saveFilters();
    applyFilters();
  });
  document.querySelectorAll(".filter").forEach((btn) => {
    btn.addEventListener("click", () => setKind(btn.dataset.kind));
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "/" && !document.querySelector("#catalog").hidden && document.activeElement !== search) {
      e.preventDefault();
      search.focus();
    }
  });
}

bootstrap();
